const COMMUNITY_KEYS=['teamTitle','teamIntro','teamNav','temporaryPortrait','sandyExperience','teamMember','sampleTitle','sampleIntro','sampleBadge','story1title','story1body','story2title','story2body','story3title','story3body','guestPending','datePending'];
const COMMUNITY={
en:['The people behind<br>your escape.','Sandy, Asier and Nacho — the team behind Explore Sumatra Escape.','Our team','TEMPORARY PORTRAIT','Local expert · 10+ years of experience','Team member','Stories from the trail.','Three sample stories to show the journeys. These are illustrative examples, not genuine guest reviews.','SAMPLE STORY · NOT A GUEST REVIEW','A day among the trees','“We set out from Bukit Lawang in the morning, following the forest trails and pausing to watch the canopy. Lunch in the jungle gave us time to slow down before returning to the village.”','Waking beside the river','“The first day ended at a simple camp by the river. After dinner, the forest grew louder. We woke to running water, shared breakfast and made our way back to Bukit Lawang.”','Three days, a different rhythm','“With two nights in the forest, we had time to settle into the pace of the trail. We walked, stopped, listened and moved on. The quiet moments stayed with us as much as the wildlife.”','Guest name to be added','Real visit date to be added'],
es:['Las personas detrás<br>de tu escapada.','Sandy, Asier y Nacho — el equipo de Explore Sumatra Escape.','El equipo','RETRATO TEMPORAL','Experto local · más de 10 años de experiencia','Miembro del equipo','Historias del sendero.','Tres historias de muestra para ilustrar los viajes. Son ejemplos, no reseñas reales de clientes.','HISTORIA DE MUESTRA · NO ES UNA RESEÑA REAL','Un día entre los árboles','“Salimos de Bukit Lawang por la mañana, siguiendo los senderos y parando para observar las copas. La comida en la selva nos dejó tiempo para ir sin prisa antes de volver al pueblo.”','Despertar junto al río','“El primer día terminó en un campamento sencillo junto al río. Después de cenar, la selva sonaba más fuerte. Despertamos con el agua, compartimos el desayuno y regresamos a Bukit Lawang.”','Tres días, otro ritmo','“Con dos noches en la selva, tuvimos tiempo de seguir el ritmo del sendero. Caminábamos, parábamos, escuchábamos y seguíamos. Los momentos tranquilos nos acompañaron tanto como la fauna.”','Nombre del viajero por añadir','Fecha real de visita por añadir'],
de:['Die Menschen hinter<br>deiner Reise.','Sandy, Asier und Nacho — das Team von Explore Sumatra Escape.','Unser Team','VORLÄUFIGES PORTRÄT','Lokaler Experte · über 10 Jahre Erfahrung','Teammitglied','Geschichten vom Pfad.','Drei Beispielgeschichten veranschaulichen die Reisen. Illustrative Beispiele, keine echten Gästebewertungen.','BEISPIELGESCHICHTE · KEINE ECHTE BEWERTUNG','Ein Tag zwischen den Bäumen','„Morgens brachen wir von Bukit Lawang auf, folgten den Waldpfaden und beobachteten das Blätterdach. Beim Mittagessen im Dschungel konnten wir zur Ruhe kommen, bevor wir ins Dorf zurückkehrten.“','Am Fluss aufwachen','„Der erste Tag endete in einem einfachen Camp am Fluss. Nach dem Essen wurde der Wald lauter. Wir erwachten mit dem Wasser, frühstückten gemeinsam und kehrten nach Bukit Lawang zurück.“','Drei Tage, ein anderer Rhythmus','„Mit zwei Nächten im Wald fanden wir Zeit, uns dem Tempo des Pfads anzupassen. Wir gingen, hielten an, hörten zu und gingen weiter. Die ruhigen Momente blieben ebenso wie die Tierwelt.“','Gastname wird ergänzt','Echtes Besuchsdatum wird ergänzt'],
fr:['Les personnes derrière<br>votre voyage.','Sandy, Asier et Nacho — l’équipe d’Explore Sumatra Escape.','Notre équipe','PORTRAIT TEMPORAIRE','Expert local · plus de 10 ans d’expérience','Membre de l’équipe','Récits des sentiers.','Trois récits de démonstration pour illustrer les voyages. Ce sont des exemples, pas de véritables avis clients.','RÉCIT D’EXEMPLE · PAS UN VRAI AVIS','Une journée parmi les arbres','« Nous sommes partis de Bukit Lawang le matin, suivant les sentiers et observant la canopée. Le déjeuner en forêt nous a permis de ralentir avant de rentrer au village. »','Se réveiller près de la rivière','« La première journée s’est terminée dans un camp simple près de la rivière. Après le dîner, la forêt est devenue plus sonore. Réveillés par l’eau, nous avons partagé le petit-déjeuner avant de revenir. »','Trois jours, un autre rythme','« Avec deux nuits en forêt, nous avons trouvé le temps de suivre le rythme du sentier. Marcher, s’arrêter, écouter, repartir. Les moments calmes nous ont autant marqués que la faune. »','Nom du voyageur à ajouter','Date réelle du séjour à ajouter'],
it:['Le persone dietro<br>il tuo viaggio.','Sandy, Asier e Nacho — il team di Explore Sumatra Escape.','Il team','RITRATTO TEMPORANEO','Esperto locale · oltre 10 anni di esperienza','Membro del team','Storie dal sentiero.','Tre storie di esempio per illustrare i viaggi. Sono esempi, non recensioni autentiche degli ospiti.','STORIA DI ESEMPIO · NON È UNA RECENSIONE REALE','Un giorno tra gli alberi','“Siamo partiti da Bukit Lawang al mattino, seguendo i sentieri e osservando la volta verde. Il pranzo nella giungla ci ha dato tempo per rallentare prima di tornare al villaggio.”','Svegliarsi accanto al fiume','“Il primo giorno è finito in un campo semplice sul fiume. Dopo cena la foresta era più sonora. Ci siamo svegliati con l’acqua, abbiamo condiviso la colazione e siamo tornati a Bukit Lawang.”','Tre giorni, un altro ritmo','“Con due notti nella foresta abbiamo trovato tempo per seguire il ritmo del sentiero. Camminare, fermarsi, ascoltare, ripartire. I momenti tranquilli ci sono rimasti quanto la fauna.”','Nome del viaggiatore da aggiungere','Data reale della visita da aggiungere'],
nl:['De mensen achter<br>jouw reis.','Sandy, Asier en Nacho — het team van Explore Sumatra Escape.','Ons team','TIJDELIJK PORTRET','Lokale expert · meer dan 10 jaar ervaring','Teamlid','Verhalen van het pad.','Drie voorbeeldverhalen laten de reizen zien. Illustratieve voorbeelden, geen echte gastenbeoordelingen.','VOORBEELDVERHAAL · GEEN ECHTE BEOORDELING','Een dag tussen de bomen','“We vertrokken ’s morgens uit Bukit Lawang, volgden de bospaden en keken naar het bladerdak. De lunch in de jungle gaf ons tijd om te vertragen voordat we terugkeerden naar het dorp.”','Wakker worden aan de rivier','“De eerste dag eindigde in een eenvoudig rivierkamp. Na het eten werd het bos luider. We werden wakker met stromend water, deelden het ontbijt en keerden terug naar Bukit Lawang.”','Drie dagen, een ander ritme','“Met twee nachten in het bos hadden we tijd om het tempo van het pad te volgen. Wandelen, stoppen, luisteren, verdergaan. De rustige momenten bleven net zo bij als de dieren.”','Naam reiziger volgt','Echte bezoekdatum volgt'],
pt:['As pessoas por trás<br>da sua viagem.','Sandy, Asier e Nacho — a equipa da Explore Sumatra Escape.','A equipa','RETRATO TEMPORÁRIO','Especialista local · mais de 10 anos de experiência','Membro da equipa','Histórias do trilho.','Três histórias de exemplo para ilustrar as viagens. São exemplos, não avaliações reais de hóspedes.','HISTÓRIA DE EXEMPLO · NÃO É UMA AVALIAÇÃO REAL','Um dia entre as árvores','“Partimos de Bukit Lawang de manhã, seguindo os trilhos e observando a copa. O almoço na selva deu-nos tempo para abrandar antes de regressar à aldeia.”','Acordar junto ao rio','“O primeiro dia acabou num acampamento simples junto ao rio. Depois do jantar, a floresta ficou mais sonora. Acordámos com a água, partilhámos o pequeno-almoço e regressámos a Bukit Lawang.”','Três dias, outro ritmo','“Com duas noites na floresta tivemos tempo para seguir o ritmo do trilho. Caminhar, parar, ouvir, continuar. Os momentos tranquilos ficaram connosco tanto como a fauna.”','Nome do viajante por adicionar','Data real da visita por adicionar']
};
for(const code of Object.keys(COMMUNITY)){if(COMMUNITY[code].length!==COMMUNITY_KEYS.length)throw Error('Community translation '+code);COMMUNITY_KEYS.forEach((key,i)=>UI[code][key]=COMMUNITY[code][i]);}
function renderCommunity(){
 const members=[{name:'Sandy',role:'Chief Experience Officer',image:'team-sandy.svg',expert:true},{name:'Asier',role:'CEO',image:'team-asier.svg'},{name:'Nacho',role:'COO',image:'team-nacho.svg'}];
 q('#team-grid').innerHTML=members.map(m=>`<article class="team-card"><figure class="team-portrait"><img src="assets/${m.image}" alt="${escapeHTML(t('temporaryPortrait')+' · '+m.name)}" width="400" height="400" loading="lazy"><figcaption>${escapeHTML(t('temporaryPortrait'))}</figcaption></figure><div class="team-info"><h3>${m.name}</h3><p class="team-role">${m.role}</p>${m.expert?`<p class="team-bio">${escapeHTML(t('sandyExperience'))}</p>`:''}</div></article>`).join('');
 q('#story-grid').innerHTML=[0,1,2].map((n)=>`<article class="sample-story"><div class="sample-label">${escapeHTML(t('sampleBadge'))}</div><div class="story-route">${escapeHTML(R[lang][n][0])}</div><h3>${escapeHTML(t('story'+(n+1)+'title'))}</h3><p class="story-text">${escapeHTML(t('story'+(n+1)+'body'))}</p><dl><dt>${escapeHTML(t('guest'))}</dt><dd>${escapeHTML(t('guestPending'))}</dd><dt>${escapeHTML(t('visit'))}</dt><dd>${escapeHTML(t('datePending'))}</dd></dl></article>`).join('');
}
